const fields=[{key:'weaponRangeMin',label:'ระยะใกล้สุดของอาวุธ (ช่อง)',type:'number',default:1,group:'weaponRange',hint:'0–20 ช่อง ใช้กับทุกพื้นที่ เช่น ธนูขั้นต่ำ 2 จะยิงตัวที่อยู่ติดกันไม่ได้'},{key:'weaponRangeMax',label:'ระยะไกลสุดของอาวุธแบบเดิม (ช่อง)',type:'number',default:-1,group:'weaponRange',hint:'-1 ใช้ระยะตามประเภทเดิม หรือ 1–20 ช่อง; ถ้าเลือกรูปพื้นที่ ให้ใช้ขนาด/ระยะในกลุ่มรูปพื้นที่แทน'},...G.fields.map(f=>({...f}))];
