function validate(v){need(v&&v.v===1&&Number.isInteger(v.min)&&v.min>=0&&v.min<=20&&Number.isInteger(v.max)&&v.max>=1&&v.max<=20&&(!v.grid?v.min<=v.max:true),'ระยะอาวุธ: ขั้นต่ำ 0–20 และสูงสุด 1–20 (ขั้นต่ำต้องไม่เกินสูงสุดเมื่อใช้รูปแบบเดิม)');if(v.grid)G.validate(v.grid);return v;}
function fromRecord(r,fallback){const max=r.weaponRangeMax??-1;need(Number.isInteger(max)&&(max===-1||max>=1&&max<=20),'ระยะไกลสุดอาวุธต้องเป็น -1 หรือ 1–20');return validate({v:1,min:r.weaponRangeMin??1,max:max===-1?fallback:max,grid:G.fromRecord(r)});}
function baseRule(w){const v=w.weaponPattern;return {min:v?.min??1,max:v?.max??w.range,mode:'single',count:1,heights:(v?.max??w.range)>1?[-2,-1,0,1,2]:[-1,0,1],side:'enemy'};}
function hands(p){const N=g.DecideCreation||(typeof require==='function'?require('./creation-data'):null);return [{hand:'main',w:p.catalogWeapon||N.weapons[p.main]},...(p.off&&p.off!=='shield'?[{hand:'off',w:p.catalogOff||N.weapons[p.off]}]:[])].filter(x=>x.w);}
