function plans(e,p,ids,aim,direction=e.gridDirection??-1){if(!Number.isInteger(aim)){const target=e.units.find(t=>t.id===(Array.isArray(ids)?ids[0]:ids));aim=D.index(target?.n??p.n);}need(e.scene.cells[aim],'เลือกช่องเล็งอาวุธในสนาม');const result=hands(p).map(h=>({...plan(e,p,h.w,ids,aim,direction),hand:h.hand})),wanted=Array.isArray(ids)?ids:ids?[ids]:[];need(new Set(wanted).size===wanted.length&&wanted.every(id=>typeof id==='string'),'รายการเป้าหมายอาวุธซ้ำหรือไม่ถูกต้อง');if(result.every(r=>r.selection!=='all'))need(wanted.every(id=>result.some(r=>r.valid.some(t=>t.id===id))),'เป้าหมายอยู่นอกระยะ/พื้นที่ของอาวุธทั้งสองมือ');need(result.some(r=>r.targets.length),'ไม่มีเป้าหมายที่มองเห็นในระยะ/พื้นที่อาวุธ');return result;}
function scope(e,plan,fn){const beforeRule=e.currentTargeting,beforeCells=e.currentGridCells;e.currentTargeting=plan.rule;e.currentGridCells=plan.cells;try{return fn();}finally{if(beforeRule===undefined)delete e.currentTargeting;else e.currentTargeting=beforeRule;if(beforeCells===undefined)delete e.currentGridCells;else e.currentGridCells=beforeCells;}}
function preview(e,p,aim,direction=e.gridDirection??-1){const result=hands(p).map(h=>({...h,cells:cells(e,p,h.w,aim,direction),valid:available(e,p,h.w,aim,direction)}));return {hands:result,cells:[...new Set(result.flatMap(h=>h.cells))],targets:[...new Set(result.flatMap(h=>h.valid.map(t=>t.id)))]};}
